CREATE OR REPLACE VIEW datalens.v_monthly_kpis AS SELECT date_trunc('month',o.order_date)::date month,SUM(i.net_revenue) revenue,SUM(i.gross_profit) gross_profit,CASE WHEN SUM(i.net_revenue)<>0 THEN SUM(i.gross_profit)/SUM(i.net_revenue) END gross_margin_pct,COUNT(DISTINCT o.order_id) orders,SUM(i.quantity) units,CASE WHEN COUNT(DISTINCT o.order_id)<>0 THEN SUM(i.net_revenue)/COUNT(DISTINCT o.order_id) END average_order_value FROM datalens.fact_order o JOIN datalens.fact_sales i ON i.order_id=o.order_id WHERE o.order_status NOT IN ('Cancelled','Returned') GROUP BY 1;
CREATE OR REPLACE VIEW datalens.v_store_performance AS SELECT s.store_id,s.store_name,s.city,s.region,SUM(i.net_revenue) revenue,SUM(i.gross_profit) gross_profit,COUNT(DISTINCT o.order_id) orders,SUM(i.quantity) units,CASE WHEN SUM(i.net_revenue)<>0 THEN SUM(i.gross_profit)/SUM(i.net_revenue) END gross_margin_pct FROM datalens.dim_store s JOIN datalens.fact_order o ON o.store_id=s.store_id JOIN datalens.fact_sales i ON i.order_id=o.order_id WHERE o.order_status NOT IN ('Cancelled','Returned') GROUP BY 1,2,3,4;
CREATE OR REPLACE VIEW datalens.v_category_performance AS SELECT p.category,SUM(i.net_revenue) revenue,SUM(i.gross_profit) gross_profit,SUM(i.quantity) units,COUNT(DISTINCT o.order_id) orders,CASE WHEN SUM(i.net_revenue)<>0 THEN SUM(i.gross_profit)/SUM(i.net_revenue) END gross_margin_pct FROM datalens.fact_sales i JOIN datalens.fact_order o ON o.order_id=i.order_id JOIN datalens.dim_product p ON p.product_id=i.product_id WHERE o.order_status NOT IN ('Cancelled','Returned') GROUP BY 1;
CREATE OR REPLACE VIEW datalens.v_sales_detail AS SELECT o.order_id,o.order_date,o.customer_id,o.store_id,s.store_name,s.region,p.product_id,p.product_name,p.category,p.subcategory,i.quantity,i.unit_price,i.discount_pct,i.net_revenue,i.estimated_cost,i.gross_profit FROM datalens.fact_sales i JOIN datalens.fact_order o ON o.order_id=i.order_id JOIN datalens.dim_store s ON s.store_id=o.store_id JOIN datalens.dim_product p ON p.product_id=i.product_id;
CREATE OR REPLACE VIEW datalens.v_target_attainment AS SELECT t.month,t.store_id,s.store_name,s.region,t.revenue_target,COALESCE(SUM(i.net_revenue),0) actual_revenue,CASE WHEN t.revenue_target<>0 THEN COALESCE(SUM(i.net_revenue),0)/t.revenue_target END revenue_attainment_pct FROM datalens.fact_sales_target t JOIN datalens.dim_store s ON s.store_id=t.store_id LEFT JOIN datalens.fact_order o ON o.store_id=t.store_id AND date_trunc('month',o.order_date)::date=t.month AND o.order_status NOT IN ('Cancelled','Returned') LEFT JOIN datalens.fact_sales i ON i.order_id=o.order_id GROUP BY 1,2,3,4,5;
